-- QA ONLY: project vxikhdulhuvghfqeutnp. Data correction, no schema changes.
-- Align the existing web document with the QA registry; never create user acceptances.
BEGIN;
SET LOCAL lock_timeout = '5s';
LOCK TABLE public.documentos_legales IN SHARE ROW EXCLUSIVE MODE;
DO $guard$
BEGIN
  IF (SELECT count(*) FROM public.documentos_legales WHERE vigente AND tipo IN ('terminos','privacidad')) <> 2 THEN
    RAISE EXCEPTION 'Unexpected active legal registry; no changes applied';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.documentos_legales WHERE tipo='terminos' AND version='2026-09-05' AND vigente AND contenido_sha256='97a59ec3596c763d7cdd2b788006b51903aeee1ba2ddf6a4c682a60ce21249a7') THEN
    RAISE EXCEPTION 'Terms registry changed; no changes applied';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.documentos_legales WHERE tipo='privacidad' AND version='2026-09-05' AND contenido_sha256='bcfb5a02d827fb46b6273b71db36452ee273753f06ea8fa9decd6953e070c255') THEN
    RAISE EXCEPTION 'Previous privacy registry changed; no changes applied';
  END IF;
  IF EXISTS (SELECT 1 FROM public.documentos_legales WHERE tipo='privacidad' AND vigente AND version NOT IN ('2026-09-05','2026-09-10')) THEN
    RAISE EXCEPTION 'A newer privacy version is active; no changes applied';
  END IF;
  IF EXISTS (SELECT 1 FROM public.documentos_legales WHERE tipo='privacidad' AND version='2026-09-10' AND (contenido_sha256 <> '738d9170436965970bc90638e57a22c2b0c04ff5352e1fe159d780b4f1875617' OR url <> 'https://padbolmatch.com/legal/privacidad-2026-09-10.html')) THEN
    RAISE EXCEPTION 'Privacy version already exists with different content; no changes applied';
  END IF;
END;
$guard$;
INSERT INTO public.documentos_legales (tipo, version, url, contenido_canonico, contenido_sha256, publicado_at, vigente)
VALUES ('privacidad', '2026-09-10', 'https://padbolmatch.com/legal/privacidad-2026-09-10.html', '{"document":"privacy","locale":"es","version":"2026-09-10","url":"https://padbolmatch.com/legal/privacidad-2026-09-10.html","content":{"title":"Política de Privacidad","lead":"Te explicamos claramente qué datos usamos en Padbol Match y con qué fines. Puedes contactarnos cuando quieras.","dataTitle":"Qué datos recolectamos","dataIntro":"Según cómo uses la cuenta y el perfil, podemos tratar, entre otros:","dataName":"Nombre y apellido","dataEmail":"Correo electrónico","dataPhone":"Teléfono y número de WhatsApp","dataProfile":"Género u otra información de perfil deportivo que indiques","dataPhoto":"Foto de perfil, si la subes","dataActivity":"Historial de reservas y participación en torneos dentro de la plataforma","dataTechnical":"Datos técnicos mínimos, como el tipo de dispositivo o registros de seguridad, necesarios para prestar el servicio","useTitle":"Para qué usamos tus datos","useBookings":"Gestionar reservas de Padbol Courts y pagos asociados","useTournaments":"Organizar torneos e inscribir participantes","useNotifications":"Enviarte notificaciones relacionadas con el servicio, como confirmaciones, cambios y recordatorios","useCommunity":"Ofrecer funciones de comunidad y búsqueda de compañeros deportivos cuando estén habilitadas en la aplicación","useSecurity":"Mejorar la seguridad, prevenir el fraude y cumplir obligaciones legales","noSaleTitle":"No vendemos tus datos","noSaleBody":"No vendemos tu información personal a terceros para que realicen marketing ajeno a Padbol Match. Solo compartimos datos cuando es necesario para prestar el servicio, por ejemplo con la sede donde reservaste, o cuando la ley lo exige.","paymentsTitle":"Pagos: Mercado Pago y Stripe","paymentsBody":"Los cobros pueden procesarse mediante Mercado Pago y/o Stripe. Esos proveedores reciben solo los datos necesarios para la transacción y aplican sus propias políticas de privacidad y seguridad:","privacyPolicyLink":"política de privacidad","privacyCenterLink":"centro de privacidad","deletionTitle":"Derecho a eliminar tu cuenta y tus datos","deletionPrefix":"Puedes iniciar la solicitud desde Mi perfil o consultar el proceso completo en","deletionMiddle":". Si no puedes ingresar, también puedes escribir desde el correo asociado a tu cuenta a","deletionSuffix":". Algunos datos pueden conservarse durante el plazo que exija la ley, por ejemplo registros contables o reclamos.","cookiesTitle":"Cookies y tecnologías similares","cookiesBody":"Usamos solo las cookies y el almacenamiento local necesarios para que la sesión funcione, recordar preferencias básicas y mantener segura la aplicación. No usamos cookies publicitarias de terceros con fines de perfilado comercial.","gdprTitle":"Usuarios en Europa (GDPR)","gdprBody":"Si resides en el Espacio Económico Europeo o en el Reino Unido, en general tienes derechos reconocidos por el RGPD (GDPR): acceder a tus datos, rectificarlos, limitar u oponerte a ciertos tratamientos, solicitar portabilidad cuando corresponda y presentar una reclamación ante la autoridad de protección de datos de tu país. Para ejercer estos derechos, escríbenos al correo de contacto indicado abajo.","contactTitle":"Contacto por privacidad","contactBody":"Consultas sobre esta política o sobre tus datos:","pushTitle":"Notificaciones en tu dispositivo","pushData":"Si activas las notificaciones del dispositivo, asociamos a tu cuenta un token de notificaciones de Expo, la plataforma Android o iOS, un identificador aleatorio de esta instalación y el idioma de la app. El identificador se genera en la instalación; no es el número de serie del teléfono. También guardamos tus preferencias de avisos operativos y promocionales y las fechas de registro, actualización y baja. Estos datos permiten dirigir los avisos a tu instalación, usar el idioma elegido, actualizar un token que cambie y respetar tus preferencias.","pushChoice":"Las notificaciones del dispositivo son opcionales. Puedes usar la app y consultar los avisos disponibles dentro de ella sin conceder ese permiso. El permiso se solicita al activar esta función; si ya lo concediste, la app puede actualizar el registro al iniciar sesión, volver a primer plano o cambiar de idioma. Los avisos operativos sobre tu actividad están activados por defecto en las preferencias de la cuenta, pero necesitan el permiso del dispositivo y un registro válido para llegar como notificación push. Las comunicaciones promocionales están desactivadas por defecto y requieren una elección separada. La constancia de lectura de esta política no activa las comunicaciones promocionales.","pushProviders":"Nuestro backend alojado en Render prepara las notificaciones y utiliza Supabase para guardar el registro de la instalación, las preferencias y los registros de operación. Para entregar un aviso, Expo recibe el token de destino, el título, el mensaje y los datos limitados del evento necesarios para abrir la sección correspondiente de la app. Expo lo transmite a Firebase Cloud Messaging de Google en Android o a Apple Push Notification service en iOS. Estos proveedores intervienen en el tratamiento y la entrega de la notificación; esta política no atribuye a todos ellos un mismo país de alojamiento o plazo de conservación.","pushRecords":"Conservamos registros de registro, rotación y baja de tokens, cambios de preferencias e intentos de envío para gestionar las entregas, detectar errores y atender consultas. Incluyen identificadores de cuenta e instalación cuando corresponde, fechas, una huella del token, categoría y evento del aviso, título, mensaje, datos de navegación, identificador del envío, estados o errores y comprobantes técnicos de Expo. Los envíos administrativos también registran quién los ordenó. Un comprobante técnico no demuestra que hayas leído el aviso.","pushControls":"Puedes cambiar las preferencias de avisos operativos y promocionales dentro de la app y retirar el permiso de notificaciones en los ajustes de Android o iOS. Los cambios de preferencias se confirman cuando el servidor los guarda. La vista previa del título y del mensaje, incluso en la pantalla bloqueada, depende de los ajustes de tu dispositivo. Desactivar los avisos promocionales no impide que uses tu cuenta.","pushRevocation":"Al cerrar sesión, la app intenta dar de baja el registro de notificaciones. Si no puede completar la baja, por ejemplo por falta de conexión, puede conservar localmente una solicitud pendiente protegida con el almacenamiento seguro del dispositivo y reintentarla cuando vuelvas a iniciar sesión con la misma cuenta. Esa solicitud contiene los identificadores necesarios para la baja, sin guardar tu contraseña ni las credenciales de sesión. El identificador aleatorio de instalación puede permanecer en el almacenamiento local. Puedes retirar el permiso en los ajustes del dispositivo para impedir la presentación de notificaciones mientras se resuelve una baja pendiente.","pushRetention":"Dar de baja o invalidar un token lo desactiva para nuevos envíos desde nuestro servicio; no elimina automáticamente todos los registros anteriores. Los registros de entrega y auditoría pueden conservar huellas, texto y metadatos aunque se elimine la referencia directa a la cuenta. Solicitar la eliminación de la cuenta tampoco equivale a una eliminación inmediata de esos registros o de copias de respaldo. Para pedir acceso, corrección o supresión de estos datos, utiliza el canal de privacidad indicado al final de esta política."},"fixedContent":{"operator":"ENTERTAINMENT SPORT SERVICE LLC","registeredAddress":"30 N Gould St Ste R, Sheridan, WY 82801, USA","processors":[{"name":"Mercado Pago","url":"https://www.mercadopago.com.ar/privacidad"},{"name":"Stripe","url":"https://stripe.com/privacy"}],"accountDeletionUrl":"https://padbolmatch.com/eliminar-cuenta","contactEmail":"padbolmatch@padbol.com"}}', '738d9170436965970bc90638e57a22c2b0c04ff5352e1fe159d780b4f1875617', now(), false)
ON CONFLICT (tipo, version) DO NOTHING;
UPDATE public.documentos_legales SET vigente=false WHERE tipo='privacidad' AND version='2026-09-05' AND vigente;
UPDATE public.documentos_legales SET vigente=true WHERE tipo='privacidad' AND version='2026-09-10' AND contenido_sha256='738d9170436965970bc90638e57a22c2b0c04ff5352e1fe159d780b4f1875617' AND NOT vigente;
DO $verify$
DECLARE state jsonb := public.estado_aceptacion_legal_actual();
BEGIN
  IF state->>'terms_version' <> '2026-09-05' OR state->>'privacy_version' <> '2026-09-10' THEN
    RAISE EXCEPTION 'Version verification failed';
  END IF;
END;
$verify$;
SELECT tipo, version, vigente, contenido_sha256 FROM public.documentos_legales WHERE tipo IN ('terminos','privacidad') ORDER BY tipo,version;
COMMIT;
